import SwiftUI

private let forest = Color(red:0.145,green:0.298,blue:0.231)
private let paper = Color(red:0.973,green:0.961,blue:0.929)
private let saddle = Color(red:0.47,green:0.33,blue:0.23)
private func ink(_ hex:String)->Color { let n=UInt64(hex.dropFirst(),radix:16) ?? 0; return Color(red:Double((n>>16)&255)/255,green:Double((n>>8)&255)/255,blue:Double(n&255)/255) }
private struct ProgressRecord:Codable {let placed:[Placement];let moves:Int;let hints:Int;let elapsed:Double;let finished:Bool;let start:String?;let finish:String?}
@MainActor final class Game:ObservableObject {
 let data:GameData;let repository:any LeaderboardRepository
 @Published var screen="home";@Published var level:Level;@Published var placed:[Placement]=[];@Published var selected:Int?;@Published var rotation=0;@Published var moves=0;@Published var hints=0;@Published var message="";@Published var running=false;@Published var progress=0.0;@Published var dialog="";@Published var elapsed=0.0;@Published var clockTick=0
 @Published var chosenStart="";@Published var chosenFinish=""
 var startGate:String {level.start.isEmpty ? chosenStart:level.start}
 var finishGate:String {level.finish.isEmpty ? chosenFinish:level.finish}
 var route:[RouteStep]=[];private var started:Double?;private var history:[([Placement],Int,Int)]=[];private var runTask:Task<Void,Never>?
 init(){let url=Bundle.main.url(forResource:"game-data",withExtension:"json")!;data=try!JSONDecoder().decode(GameData.self,from:Data(contentsOf:url));level=data.levels[0];repository=LocalLeaderboard()}
 var time:Double {elapsed+(started.map{ProcessInfo.processInfo.systemUptime-$0} ?? 0)}
 func resume(){if started==nil && screen=="game" && !running && dialog.isEmpty {started=ProcessInfo.processInfo.systemUptime}}
 func pause(){if let start=started{elapsed+=ProcessInfo.processInfo.systemUptime-start};started=nil;save()}
 func save(){guard screen != "home" else{return};let r=ProgressRecord(placed:placed,moves:moves,hints:hints,elapsed:time,finished:running||screen=="win",start:chosenStart,finish:chosenFinish);if let d=try?JSONEncoder().encode(r){UserDefaults.standard.set(d,forKey:"level-\(level.id)")}}
 func start(_ l:Level){pause();runTask?.cancel();level=l;screen="game";running=false;placed=[];moves=0;hints=0;elapsed=0;history=[];route=[];chosenStart="";chosenFinish="";if let d=UserDefaults.standard.data(forKey:"level-\(l.id)"),let p=try?JSONDecoder().decode(ProgressRecord.self,from:d),!p.finished{for tile in p.placed where l.sequence.contains(tile.id)&&data.fits(tile,placed){placed.removeAll{$0.id==tile.id};placed.append(tile)};moves=p.moves;hints=p.hints;elapsed=p.elapsed;chosenStart=p.start ?? "";chosenFinish=p.finish ?? ""};selected=l.requiredPieces.first{n in !placed.contains{$0.id==n}};rotation=0;message="拼板按编号排列 · 正确后自动出发";resume()}
 func home(){pause();runTask?.cancel();screen="home";running=false}
 func select(_ id:Int){guard !running else{return};selected=id;rotation=placed.first{$0.id==id}?.r ?? 0;message="已选中 \(id) 号，可旋转或移动"}
 private func remember(){history.append((placed,moves,hints))}
 func place(_ x:Int,_ y:Int){guard !running,let id=selected else{return};let p=Placement(id:id,x:x,y:y,r:rotation);guard data.fits(p,placed) else{message="这里重叠或越界，已保留原位";return};remember();placed.removeAll{$0.id==id};placed.append(p);moves+=1;changed()}
 func rotate(){guard !running,let id=selected else{return};let next=(rotation+1)%4;if let i=placed.firstIndex(where:{$0.id==id}){var p=placed[i];p.r=next;guard data.fits(p,placed) else{message="旋转后重叠或越界，已保留原位";return};remember();placed[i]=p;moves+=1};rotation=next;changed()}
 func remove(){guard !running,let id=selected,placed.contains(where:{$0.id==id}) else{return};remember();placed.removeAll{$0.id==id};moves+=1;changed()}
 func undo(){guard !running,let last=history.popLast() else{return};placed=last.0;moves=last.1;hints=max(hints,last.2);changed()}
 func reset(){guard !running else{return};remember();placed=[];chosenStart="";chosenFinish="";moves+=1;changed()}
 func hint(){guard !running else{return};guard let p=level.solution.first(where:{!placed.contains($0)}) else{if level.solveEndpoints{chosenStart=level.solutionStart;chosenFinish=level.solutionFinish;hints+=1;moves+=1;changed()};return};remember();placed=placed.filter{$0.id != p.id&&data.fits(p,[$0])}+[p];selected=p.id;rotation=p.r;moves+=1;hints+=1;message="帮你摆好了 \(p.id) 号";changed()}
 func changed(){save();runTask?.cancel();guard !level.solveEndpoints || (!startGate.isEmpty && !finishGate.isEmpty),let valid=data.trace(level,placed,start:startGate,finish:finishGate) else{return};runTask=Task{try? await Task.sleep(for:.milliseconds(250));guard !Task.isCancelled else{return};pause();running=true;route=valid;progress=0;repository.save(Score(level:level.id,millis:Int(elapsed*1000),moves:moves,hints:hints,timestamp:Date()));save();let start=ProcessInfo.processInfo.systemUptime;while progress<1{guard !Task.isCancelled else{return};progress=min(1,(ProcessInfo.processInfo.systemUptime-start)/(Double(valid.count)*1.35));try? await Task.sleep(for:.milliseconds(16))};running=false;screen="win";save()}}
 func choose(_ letter:String){if dialog=="start"{chosenStart=letter}else{chosenFinish=letter};moves+=1;close();changed()}
 func show(_ type:String){guard !running else{return};pause();dialog=type}
 func close(){dialog="";resume()}
}
private func timeString(_ seconds:Double)->String {let ms=Int(seconds*1000);return String(format:"%02d:%02d.%02d",ms/60000,ms/1000%60,ms%1000/10)}
@main struct RacingClubApp:App {@StateObject private var game=Game();@Environment(\.scenePhase) private var phase;var body:some Scene{WindowGroup{ClubView(game:game).preferredColorScheme(.light).onChange(of:phase){_,p in if p == .active{game.resume()}else{game.pause()}}}}}
struct ClubView:View {
 @ObservedObject var game:Game
 private let tick=Timer.publish(every:0.1,on:.main,in:.common).autoconnect()
 var body:some View {GeometryReader{geo in VStack(spacing:8){header;if game.screen=="home"{home}else if game.screen=="win"{win}else{if geo.size.width>geo.size.height{HStack(spacing:18){NativeBoard(game:game).frame(maxWidth:.infinity,maxHeight:.infinity);workbench.frame(width:geo.size.width*0.39)}}else{VStack{NativeBoard(game:game).aspectRatio(5.7/4.7,contentMode:.fit);workbench}}}}.padding(.horizontal,18).padding(.vertical,8).background(paper).sheet(isPresented:Binding(get:{!game.dialog.isEmpty},set:{if !$0{game.close()}})){dialog}.onReceive(tick){_ in game.clockTick+=1}}
 }
 private var header:some View {HStack(spacing:12){if game.screen=="home"{Text("♞ RacingClub").font(.system(size:24,weight:.bold,design:.serif))}else{tool("chevron.left","返回"){game.home()};Text("挑战 \(game.level.number)").font(.headline);Spacer();sequence(game.level);Spacer();Text(timeString(game.time)).font(.system(size:13,design:.monospaced));tool("trophy","本关排行榜"){game.show("rank")}};if game.screen=="home"{Spacer()};tool("questionmark.circle","玩法"){game.show("help")}}.foregroundStyle(forest).frame(height:38)}
 private var home:some View {HStack(spacing:24){ZStack(alignment:.topLeading){Image("horse-arena").resizable().scaledToFill();Text("今天，\n跃过新的挑战").font(.system(size:29,weight:.bold)).foregroundStyle(forest).padding(22)}.frame(maxWidth:.infinity,maxHeight:.infinity).clipped().clipShape(RoundedRectangle(cornerRadius:16));ScrollView{VStack(alignment:.leading,spacing:15){Text("马术训练场").font(.title2.bold());ForEach(game.data.levels){level in Button{game.start(level)}label:{VStack(alignment:.leading,spacing:11){HStack{Text("挑战 \(level.number)").font(.title3.bold());Spacer();Text("入门").font(.caption)};Text(level.title).font(.caption);sequence(level)}.padding(18).background(Color.white.opacity(0.65),in:RoundedRectangle(cornerRadius:12))}.buttonStyle(.plain)};Text("本机训练记录 · 原生渲染").font(.caption2).foregroundStyle(saddle)}.foregroundStyle(forest)}.frame(maxWidth:.infinity)}}
 private var workbench:some View {VStack(spacing:8){HStack(spacing:0){Text("拼板").font(.caption.bold());Spacer();tool("rotate.right","旋转"){game.rotate()};tool("trash","移回"){game.remove()};tool("arrow.uturn.backward","撤销"){game.undo()};tool("lightbulb","提示"){game.hint()};tool("arrow.clockwise","重置"){game.reset()};tool("square.grid.2x2","全部 10 块"){game.show("inventory")}}.disabled(game.running);ScrollView{LazyVGrid(columns:Array(repeating:GridItem(.flexible(),spacing:5),count:5),spacing:6){ForEach(game.level.requiredPieces,id:\.self){id in Button{game.select(id)}label:{VStack(spacing:5){badge(id);Text(game.placed.contains{$0.id==id} ? "已放置":"待放置").font(.system(size:7));TilePreview(game:game,id:id).frame(height:36)}.padding(5).frame(maxWidth:.infinity).background(game.selected==id ? forest.opacity(0.1):Color(red:0.94,green:0.88,blue:0.76),in:RoundedRectangle(cornerRadius:7)).overlay{RoundedRectangle(cornerRadius:7).stroke(game.selected==id ? forest:Color.clear,lineWidth:2)}}.buttonStyle(.plain)}}};HStack{Text(game.selected.map{"已选中 \($0) 号 · \(game.rotation*90)°"} ?? "选择一块拼板").font(.caption2);Spacer()};Text(game.message).font(.system(size:10)).frame(maxWidth:.infinity,minHeight:24,alignment:.leading);Text("✓ 正确连接后自动出发").font(.system(size:9)).foregroundStyle(forest)}.padding(12).background(Color.white.opacity(0.5),in:RoundedRectangle(cornerRadius:12)).foregroundStyle(saddle)}
 private var win:some View {HStack(spacing:25){Image("horse-arena").resizable().scaledToFill().frame(maxWidth:.infinity,maxHeight:.infinity).clipped().clipShape(RoundedRectangle(cornerRadius:18));VStack(spacing:14){Text("漂亮，顺利通关！").font(.title.bold());Text(timeString(game.elapsed)).font(.system(size:32,design:.serif));Text("\(game.moves) 步 · \(game.hints==0 ? "独立完成":"使用提示")").font(.caption);Button(game.level.id<game.data.levels.last!.id ? "挑战下一关":"返回训练场"){if let next=game.data.levels.first(where:{$0.id>game.level.id}){game.start(next)}else{game.home()}}.buttonStyle(.borderedProminent).tint(forest);Button("查看本关排行榜"){game.show("rank")}}.frame(maxWidth:.infinity).foregroundStyle(forest)}}
 private var dialog:some View {NavigationStack{ScrollView{VStack(alignment:.leading,spacing:16){if game.dialog=="rank"{Text("挑战 \(game.level.number) · 本机排行榜").font(.title2.bold());let records=game.repository.list(level:game.level.id);if records.isEmpty{Text("还没有成绩，完成一次训练就会记录。")};ForEach(Array(records.enumerated()),id:\.element.id){i,r in HStack{Text("\(i+1)");Text(timeString(Double(r.millis)/1000)).monospacedDigit();Spacer();Text("\(r.moves) 步");Text(r.hints==0 ? "独立完成":"使用提示").font(.caption)}};Text("记录保存在此设备；线上服务尚未接入。").font(.caption)}else if game.dialog=="start" || game.dialog=="finish"{Text(game.dialog=="start" ? "选择起点":"选择终点").font(.title2.bold());HStack{ForEach(game.data.gates.keys.sorted(),id:\.self){letter in Button(letter){game.choose(letter)}.buttonStyle(.bordered)}}}else if game.dialog=="inventory"{Text("全部 10 块拼板").font(.title2.bold());LazyVGrid(columns:Array(repeating:GridItem(.flexible()),count:5)){ForEach(game.data.inventory,id:\.id){p in VStack{badge(p.id);Text(game.level.sequence.contains(p.id) ? "本关使用":"本关不用").font(.caption2)}.padding(10)}}}else{Text("一条路，刚刚好的顺序").font(.title2.bold());Text("看上方障碍顺序。点右侧编号，再点棋盘左上格放置。\n\n点已有拼板可选中，再旋转或点空格移动。重叠或越界时保留原位。\n\n正确后自动停止计时，马儿沿路跑到终点。岔路须平顺转弯，无障碍支路不计跨障。同一障碍可多次跨越。第65关起，点起终点选择字母；两端可相同。")}}.padding(25)}.foregroundStyle(forest).background(paper).toolbar{ToolbarItem(placement:.confirmationAction){Button("完成"){game.close()}}}}}
 private func tool(_ icon:String,_ label:String,_ action:@escaping()->Void)->some View {Button(action:action){Image(systemName:icon).font(.system(size:19)).frame(width:38,height:38)}.accessibilityLabel(label)}
 private func badge(_ id:Int)->some View {Text("\(id)").font(.system(size:12,weight:.bold,design:.serif)).foregroundStyle(.white).frame(width:23,height:23).background(ink(game.data.inventory.first{$0.id==id}!.color),in:Circle())}
 private func sequence(_ level:Level)->some View {ScrollView(.horizontal,showsIndicators:true){HStack(spacing:6){Text(level.start.isEmpty ? "?":level.start);ForEach(Array(level.sequence.enumerated()),id:\.offset){_,n in Text("›");badge(n)};Text("› \(level.finish.isEmpty ? "?":level.finish)")}.font(.caption).foregroundStyle(saddle)}.frame(maxWidth:350)}
}
private func drawTile(_ c:inout GraphicsContext,_ data:GameData,_ p:Placement,_ u:CGFloat,_ origin:CGPoint){let(w,h)=data.dimensions(p.r);let top=CGPoint(x:origin.x+CGFloat(p.x)*u,y:origin.y+CGFloat(p.y)*u);c.fill(Path(roundedRect:CGRect(x:top.x,y:top.y,width:CGFloat(w)*u,height:CGFloat(h)*u),cornerRadius:7),with:.color(ink("#d7b68a")));let piece=data.pieces.first{$0.id==p.id}!;for road in piece.paths {var path=Path();for(i,pt)in road.samples.enumerated(){let q=data.rotate(pt,p.r);let point=CGPoint(x:top.x+q[0]*u,y:top.y+q[1]*u);if i==0{path.move(to:point)}else{path.addLine(to:point)}};c.stroke(path,with:.color(ink("#fff2d6")),lineWidth:u*0.36)};let g=piece.gate;let q=data.rotate([g[0]/100,g[1]/100],p.r);let a=(g[2]+Double(p.r*90)) * .pi/180;let center=CGPoint(x:top.x+q[0]*u,y:top.y+q[1]*u);let dx = -sin(a)*u*0.23,dy=cos(a)*u*0.23;var gate=Path();gate.move(to:CGPoint(x:center.x-dx,y:center.y-dy));gate.addLine(to:CGPoint(x:center.x+dx,y:center.y+dy));c.stroke(gate,with:.color(ink(piece.color)),lineWidth:u*0.09)}
struct TilePreview:View {@ObservedObject var game:Game;let id:Int;var body:some View{Canvas{context,size in var c=context;let r=game.selected==id ? game.rotation:0;let(w,h)=game.data.dimensions(r);let u=min(size.width/CGFloat(w),size.height/CGFloat(h));drawTile(&c,game.data,Placement(id:id,x:0,y:0,r:r),u,CGPoint(x:(size.width-CGFloat(w)*u)/2,y:(size.height-CGFloat(h)*u)/2))}}}
struct NativeBoard:View {
 @ObservedObject var game:Game
 var body:some View {GeometryReader{geo in let u=min(geo.size.width/5.7,geo.size.height/4.7);let w=u*5.7,h=u*4.7;let pad=u*0.35;ZStack(alignment:.topLeading){Canvas{context,size in var c=context;c.fill(Path(roundedRect:CGRect(origin:.zero,size:size),cornerRadius:18),with:.color(ink("#dfbc87")));for y in 0..<4{for x in 0..<5{c.fill(Path(roundedRect:CGRect(x:pad+CGFloat(x)*u+2,y:pad+CGFloat(y)*u+2,width:u-4,height:u-4),cornerRadius:7),with:.color(ink("#c6a16d")))}};for p in game.placed{drawTile(&c,game.data,p,u,CGPoint(x:pad,y:pad));if game.selected==p.id{let(tw,th)=game.data.dimensions(p.r);c.stroke(Path(roundedRect:CGRect(x:pad+CGFloat(p.x)*u,y:pad+CGFloat(p.y)*u,width:CGFloat(tw)*u,height:CGFloat(th)*u),cornerRadius:7),with:.color(forest),lineWidth:3)};c.draw(Text("\(p.id)").font(.system(size:u*0.2,weight:.bold)).foregroundColor(forest),at:CGPoint(x:pad+(CGFloat(p.x)+0.2)*u,y:pad+(CGFloat(p.y)+0.2)*u))};for(name,pt)in game.data.gates{let x=pad+pt[0]*u+(pt[0]==0 ? -u*0.22:pt[0]==5 ? u*0.22:0);let y=pad+pt[1]*u+(pt[1]==0 ? -u*0.22:pt[1]==4 ? u*0.22:0);c.draw(Text(name).font(.system(size:u*0.22,weight:.bold)).foregroundColor(saddle),at:CGPoint(x:x,y:y))};if let end=game.data.gates[game.finishGate]{let e=CGPoint(x:pad+end[0]*u,y:pad+end[1]*u);var arch=Path();arch.move(to:CGPoint(x:e.x-u*0.22,y:e.y));arch.addLine(to:CGPoint(x:e.x-u*0.22,y:e.y-u*0.33));arch.addLine(to:CGPoint(x:e.x+u*0.22,y:e.y-u*0.33));arch.addLine(to:CGPoint(x:e.x+u*0.22,y:e.y));c.stroke(arch,with:.color(saddle),lineWidth:u*0.055)}}.contentShape(Rectangle()).gesture(SpatialTapGesture().onEnded{tap in guard !game.running else{return};let x=Int(floor((tap.location.x-pad)/u)),y=Int(floor((tap.location.y-pad)/u));guard(0..<5).contains(x),(0..<4).contains(y)else{return};if let p=game.placed.first(where:{p in let(w,h)=game.data.dimensions(p.r);return(p.x..<p.x+w).contains(x)&&(p.y..<p.y+h).contains(y)}){game.select(p.id)}else{game.place(x,y)}})
 let pos=horsePosition;let jump=jumpHeight
 if !game.startGate.isEmpty {Image("horse-pawn").resizable().scaledToFit().frame(width:u*0.65,height:u*0.65).offset(x:pad+pos[0]*u-u*0.3,y:pad+pos[1]*u-u*0.55-jump).allowsHitTesting(false)}
 HStack{Button("起点 \(game.startGate.isEmpty ? "?":game.startGate)"){if game.level.solveEndpoints{game.show("start")}};Spacer();Button("终点 \(game.finishGate.isEmpty ? "?":game.finishGate)"){if game.level.solveEndpoints{game.show("finish")}}}.font(.system(size:10,weight:.bold)).foregroundStyle(forest).frame(width:w).offset(y:h-12)

 }.frame(width:w,height:h).frame(maxWidth:.infinity,maxHeight:.infinity)}}
 private var jumpHeight:Double {guard game.running,!game.route.isEmpty else{return 0};let cursor=min(game.progress*Double(game.route.count),Double(game.route.count)-0.00001);let step=game.route[Int(cursor)];let local=cursor.truncatingRemainder(dividingBy:1);guard step.jump != nil else{return 0};let road=game.data.road(step);let along=step.from==road.from ? local:1-local;let gate=road.jumpAt ?? 0.5;return sin(Double.pi*max(0,1-abs(along-gate)*8))*14}
 private var horsePosition:[Double]{guard game.running,!game.route.isEmpty else{return game.data.gates[game.startGate] ?? [-1,-1]};let cursor=min(game.progress*Double(game.route.count),Double(game.route.count)-0.00001);return game.data.position(game.route[Int(cursor)],cursor.truncatingRemainder(dividingBy:1))}
}
